(() => {
  const copyCards = (decks, prefix) => decks.flatMap((unit) => (unit.cards || []).map((card, index) => ({
    ...card,
    id: `${prefix}-${unit.id}-${index + 1}`,
  })));
  const makeCards = (prefix, rows) => rows.map(([front, back], index) => ({ id: `${prefix}-${index + 1}`, front, back }));
  const unit = (id, name, shortName, cards, sourceUrl) => ({ id, name, shortName, builtIn: true, sourceTitle: "Official exam outline and original study material", sourceUrl, cards, questions: [], feynmanPrompts: [] });

  const datUrl = "https://www.ada.org/-/media/project/ada-organization/ada/ada-org/files/education/dat_candidate_guide.pdf";
  const datOrganic = makeCards("dat-orgo", [
    ["constitutional isomers", "Compounds with the same molecular formula but different atom-to-atom connectivity."],
    ["stereoisomers", "Compounds with the same connectivity but different three-dimensional arrangements."],
    ["enantiomers", "Nonsuperimposable mirror-image stereoisomers; in an achiral environment they share most physical properties but rotate plane-polarized light oppositely."],
    ["diastereomers", "Stereoisomers that are not mirror images and generally have different physical and chemical properties."],
    ["meso compound", "An achiral compound containing stereocenters because an internal symmetry element makes its mirror image superimposable."],
    ["racemic mixture", "A 1:1 mixture of enantiomers with no net optical rotation."],
    ["R/S assignment", "Prioritize substituents by atomic number, point the lowest priority away, then trace 1→2→3: clockwise is R and counterclockwise is S."],
    ["E/Z assignment", "Assign the higher-priority group on each alkene carbon; same side is Z and opposite sides is E."],
    ["conformational isomers", "Different spatial arrangements produced by rotation around single bonds without breaking bonds."],
    ["Newman projection", "A view directly down a carbon–carbon bond used to compare staggered, eclipsed, anti, and gauche conformations."],
    ["anti conformation", "A staggered conformation with the largest groups 180° apart; it usually has the lowest steric energy."],
    ["gauche interaction", "Steric strain between groups separated by a 60° dihedral angle in a staggered conformation."],
    ["chair conformation", "The lowest-energy cyclohexane conformation, with substituents occupying axial or equatorial positions."],
    ["ring flip", "Interconversion of cyclohexane chairs that swaps axial and equatorial positions while preserving each substituent’s up/down orientation."],
    ["1,3-diaxial interaction", "Steric repulsion experienced by an axial cyclohexane substituent with axial groups two carbons away."],
    ["nucleophile", "An electron-pair donor that attacks an electron-poor atom to form a bond."],
    ["electrophile", "An electron-pair acceptor that is attacked by a nucleophile."],
    ["leaving group", "An atom or group that departs with the bonding electron pair; weaker bases are generally better leaving groups."],
    ["SN2 reaction", "A concerted backside substitution whose rate depends on both substrate and nucleophile and produces inversion at the reacting stereocenter."],
    ["SN1 reaction", "A stepwise substitution through a carbocation intermediate whose rate depends primarily on substrate concentration."],
    ["E2 reaction", "A concerted elimination requiring a base and an antiperiplanar hydrogen–leaving-group arrangement."],
    ["E1 reaction", "A stepwise elimination through a carbocation, often competing with SN1 and favoring the more substituted alkene."],
    ["carbocation stability", "Resonance-stabilized carbocations are especially stable; among simple alkyl carbocations, tertiary > secondary > primary > methyl."],
    ["Zaitsev product", "The more substituted alkene, commonly favored in elimination when steric or structural factors do not dictate otherwise."],
    ["Hofmann product", "The less substituted alkene, often favored by bulky bases or certain leaving groups."],
    ["Markovnikov addition", "Addition across an unsymmetrical alkene in which hydrogen adds to the carbon already bearing more hydrogens."],
    ["anti-Markovnikov hydration", "Hydroboration–oxidation places OH on the less substituted alkene carbon with syn addition."],
    ["halogenation of an alkene", "Addition of Br₂ or Cl₂ through a halonium ion, producing anti vicinal dihalide addition."],
    ["ozonolysis", "Oxidative cleavage of an alkene into carbonyl compounds; product type depends on substitution and workup."],
    ["aromaticity", "A cyclic, planar, fully conjugated system containing 4n+2 π electrons."],
    ["antiaromaticity", "A cyclic, planar, fully conjugated system containing 4n π electrons; it is unusually unstable."],
    ["electrophilic aromatic substitution", "A reaction that replaces an aromatic hydrogen with an electrophile while restoring aromaticity."],
    ["ortho/para director", "A substituent that directs new electrophilic aromatic substitution mainly to positions adjacent or opposite itself; most are electron donating."],
    ["meta director", "An electron-withdrawing substituent that usually directs electrophilic aromatic substitution to the meta position."],
    ["carbonyl carbon", "The electrophilic carbon of a C=O bond because oxygen withdraws electron density."],
    ["nucleophilic addition", "Attack on an aldehyde or ketone carbonyl followed by protonation, converting the trigonal carbonyl carbon to a tetrahedral center."],
    ["nucleophilic acyl substitution", "Addition to a carboxylic-acid derivative followed by elimination of a leaving group, retaining the carbonyl."],
    ["carboxylic-acid derivative reactivity", "Acyl halide > anhydride > ester ≈ carboxylic acid > amide, largely reflecting leaving-group basicity."],
    ["Fischer esterification", "Acid-catalyzed equilibrium reaction of a carboxylic acid with an alcohol to form an ester and water."],
    ["saponification", "Base-promoted ester hydrolysis that forms a carboxylate salt and an alcohol."],
    ["amide hydrolysis", "Cleavage of an amide under strong acidic or basic conditions to produce a carboxylic acid/carboxylate and an amine/ammonium species."],
    ["aldol reaction", "An enolate adds to an aldehyde or ketone to form a β-hydroxy carbonyl; dehydration may produce an α,β-unsaturated carbonyl."],
    ["Grignard reagent", "An organomagnesium nucleophile that forms carbon–carbon bonds by attacking electrophiles and must be kept away from protic substances."],
    ["oxidation of a primary alcohol", "A primary alcohol can oxidize to an aldehyde under mild conditions or to a carboxylic acid under stronger aqueous conditions."],
    ["oxidation of a secondary alcohol", "A secondary alcohol oxidizes to a ketone."],
    ["reduction of an aldehyde or ketone", "Hydride reagents reduce aldehydes to primary alcohols and ketones to secondary alcohols."],
    ["infrared spectroscopy", "Identifies bond vibrations; broad O–H, sharp C=O, and diagnostic fingerprint-region absorptions help identify functional groups."],
    ["¹H NMR integration", "The relative area under a signal is proportional to the number of hydrogens producing it."],
    ["¹H NMR splitting", "Equivalent neighboring hydrogens commonly split a signal into n+1 peaks when simple first-order coupling applies."],
    ["chemical shift", "An NMR signal’s position relative to a reference; electron-withdrawing environments generally move signals downfield."],
    ["mass spectrometry molecular ion", "The molecular ion or related parent peak helps estimate molecular mass; fragmentation patterns provide structural evidence."],
    ["thin-layer chromatography Rf", "Rf = distance traveled by compound ÷ distance traveled by solvent front; under fixed conditions, less polar compounds travel farther on polar silica."],
    ["extraction", "Separates compounds by their different solubilities between immiscible liquid phases; acid–base chemistry can move an analyte between layers."],
    ["recrystallization", "Purifies a solid by dissolving it in hot solvent and allowing purer crystals to form as the solution cools."],
    ["simple distillation", "Separates a volatile liquid from nonvolatile material or liquids with widely separated boiling points."],
    ["fractional distillation", "Uses repeated vaporization–condensation cycles to separate liquids with closer boiling points."],
    ["chromatography", "Separates mixture components through different affinities for stationary and mobile phases."],
  ]);

  const datPat = makeCards("dat-pat", [
    ["Apertures strategy", "Track the object’s maximum width, height, and depth, then test whether a single rigid orientation can pass completely through the opening."],
    ["Apertures elimination", "Reject an opening when any required dimension is too small or when protrusions cannot fit simultaneously; rotation cannot deform the object."],
    ["View recognition", "Match top, front, and end views by projecting edges and surfaces orthogonally rather than imagining perspective."],
    ["Visible line", "A solid line in an orthographic view represents an edge directly visible from that viewing direction."],
    ["Hidden line", "A dashed line represents an edge blocked by material from the chosen viewing direction."],
    ["View alignment", "Corresponding widths align between top and front views, while corresponding depths align between top and end views."],
    ["Angle discrimination", "Compare the separation near the vertex and mentally extend both rays; do not judge by line length or orientation."],
    ["Acute-angle comparison", "When angles are close, compare a consistent small distance from each vertex rather than the endpoints."],
    ["Paper-fold reflection", "Every unfolding reflects existing holes across the most recent fold line; reverse the folds one at a time."],
    ["Hole on a fold", "A hole lying exactly on a fold line does not duplicate across that fold when the paper is unfolded."],
    ["Layer count", "Each ordinary fold doubles the number of layers pierced unless the punch lies on an edge or fold that changes symmetry."],
    ["Cube counting", "Classify only cubes that actually exist, count painted exposed faces, and avoid counting hidden empty positions as cubes."],
    ["Cube map", "Record the height of each footprint position; use neighboring heights to determine which side faces are exposed."],
    ["Interior cube", "A cube has zero painted faces only when cubes or contacts cover every exterior face in the painted original structure."],
    ["Three-painted-face cube", "A cube with three painted faces lies at an exposed convex corner of the structure."],
    ["Pattern folding", "Choose one face as an anchor and track which faces become opposite or adjacent as the net folds."],
    ["Opposite faces", "Faces separated by a hinge chain may become opposite; faces sharing an edge in the net cannot become opposite after folding."],
    ["Edge compatibility", "Mark distinctive symbols near specific edges and verify that those same edges meet in the folded object."],
    ["Spatial relations", "Rotate the whole object mentally without reflecting it; a mirror image cannot be produced by rotation alone."],
    ["Chirality check", "Track the clockwise order of three neighboring features; rotation preserves the order while reflection reverses it."],
    ["PAT pacing", "Move on when a comparison becomes costly, mark it, and return later; all six subtests reward consistent accuracy under time pressure."],
    ["PAT external knowledge", "Perceptual Ability assesses spatial visualization, not memorized scientific facts or artistic drawing skill."],
  ]);

  const datReading = makeCards("dat-reading", [
    ["passage map", "A brief record of each paragraph’s role—background, claim, evidence, contrast, or implication—used to retrieve details efficiently."],
    ["main idea", "The passage’s central claim or organizing purpose, broad enough to cover the whole text but specific enough to exclude nearby topics."],
    ["author’s purpose", "What the author is doing—explaining, comparing, criticizing, defending, or proposing—not merely the passage topic."],
    ["supported inference", "A conclusion that follows from the passage with minimal additional assumptions."],
    ["detail question", "Return to the relevant lines and use their local context; memory alone invites attractive but distorted choices."],
    ["tone", "The author’s attitude inferred from evaluative wording, qualifications, and emphasis rather than from subject matter alone."],
    ["scope trap", "An answer that may be true but reaches beyond the people, time, conditions, or claim discussed in the passage."],
    ["degree trap", "An answer that changes a qualified claim into an absolute one through words such as always, never, proves, or entirely."],
    ["opposite answer", "A choice that uses passage language while reversing the stated relationship or conclusion."],
    ["new-information trap", "A plausible statement not established by the passage and therefore unsupported for a passage-based question."],
    ["scientific passage structure", "Often moves from problem or prior model to method/evidence, result, and interpretation; mark competing hypotheses explicitly."],
    ["reference resolution", "Identify the exact noun or idea a pronoun or phrase refers to by checking grammatical fit and nearby logic."],
    ["paragraph transition", "Words such as however, therefore, similarly, and for example reveal the relationship between claims."],
    ["answer-choice comparison", "When two choices seem plausible, ask which one is fully supported and which adds an unsupported word, cause, or degree."],
    ["reading pacing", "Budget time across three passages and their questions while preserving enough time to verify evidence for uncertain answers."],
  ]);

  const datQr = makeCards("dat-qr", [
    ["percent change", "Percent change = (new − original) ÷ original × 100%."],
    ["weighted average", "Weighted average = Σ(value × weight) ÷ Σweights."],
    ["distance-rate-time", "d = rt; keep units consistent before substituting."],
    ["work-rate equation", "If one worker finishes in a hours, its rate is 1/a job per hour; combined rates add."],
    ["simple interest", "I = Prt, where P is principal, r is the rate per time period, and t is the number of periods."],
    ["compound growth", "Future value = P(1 + r/n)^(nt), or P(1+r)^t when compounding once per period."],
    ["arithmetic sequence", "aₙ = a₁ + (n−1)d; Sₙ = n(a₁+aₙ)/2."],
    ["geometric sequence", "aₙ = a₁r^(n−1); finite sum Sₙ = a₁(1−rⁿ)/(1−r) for r ≠ 1."],
    ["quadratic formula", "For ax²+bx+c=0, x = (−b ± √(b²−4ac))/(2a)."],
    ["discriminant", "b²−4ac: positive gives two real roots, zero one repeated real root, and negative no real roots."],
    ["exponent product rule", "xᵃxᵇ = xᵃ⁺ᵇ."],
    ["negative exponent", "x⁻ⁿ = 1/xⁿ for x ≠ 0."],
    ["absolute-value equation", "|x|=a has x=a or x=−a when a≥0."],
    ["absolute-value inequality", "|x|<a means −a<x<a; |x|>a means x<−a or x>a for a>0."],
    ["ratio proportion", "For a/b=c/d, cross-products satisfy ad=bc when denominators are nonzero."],
    ["direct variation", "y=kx; the ratio y/x remains constant."],
    ["inverse variation", "y=k/x; the product xy remains constant."],
    ["slope", "m=(y₂−y₁)/(x₂−x₁), representing vertical change per unit horizontal change."],
    ["line equation", "Slope-intercept form is y=mx+b; point-slope form is y−y₁=m(x−x₁)."],
    ["parallel and perpendicular slopes", "Distinct parallel lines have equal slopes; nonvertical perpendicular lines have slopes whose product is −1."],
    ["function composition", "(f∘g)(x)=f(g(x)); evaluate the inner function first."],
    ["probability complement", "P(not A)=1−P(A)."],
    ["independent events", "For independent events, P(A and B)=P(A)P(B)."],
    ["conditional probability", "P(A|B)=P(A∩B)/P(B), provided P(B)>0."],
    ["permutation", "An ordered selection of r objects from n: nPr=n!/(n−r)!."],
    ["combination", "An unordered selection of r objects from n: nCr=n!/[r!(n−r)!]."],
    ["mean", "The sum of values divided by the number of values; it is sensitive to outliers."],
    ["median", "The middle ordered value, resistant to extreme values."],
    ["standard deviation", "A measure of typical spread around the mean; larger values indicate greater dispersion."],
    ["data sufficiency", "Decide whether the statements provide enough information for a unique answer, not whether you can estimate one."],
    ["quantitative comparison", "Compare strategically using algebra, boundary cases, and permissible values rather than fully computing whenever possible."],
    ["triangle area", "A = ½bh."],
    ["Pythagorean theorem", "For a right triangle with legs a and b and hypotenuse c, a²+b²=c²."],
    ["circle formulas", "Circumference C=2πr and area A=πr²."],
    ["rectangular solid", "Volume V=lwh; surface area SA=2lw+2lh+2wh."],
    ["cylinder", "Volume V=πr²h; total surface area SA=2πr²+2πrh."],
    ["similar figures", "Corresponding lengths scale by k, areas by k², and volumes by k³."],
    ["unit conversion", "Multiply by conversion factors arranged so unwanted units cancel."],
    ["estimation", "Round deliberately to test answer-choice scale and catch impossible exact calculations."],
    ["graph interpretation", "Read axes, units, scale, and whether the graph shows totals, rates, percentages, or cumulative values before calculating."],
  ]);

  window.DAT_DECKS = [
    unit("dat-biology", "DAT · Biology", "Biology", copyCards(window.AP_BIOLOGY_DECKS || [], "dat-bio"), datUrl),
    unit("dat-general-chemistry", "DAT · General Chemistry", "General Chemistry", copyCards(window.AP_CHEMISTRY_DECKS || [], "dat-gchem"), datUrl),
    unit("dat-organic-chemistry", "DAT · Organic Chemistry", "Organic Chemistry", [...copyCards((window.MCAT_REVIEW_DECKS || []).filter((item) => item.id === "mcat-theme-7"), "dat-mcat-orgo"), ...datOrganic], datUrl),
    unit("dat-perceptual-ability", "DAT · Perceptual Ability", "Perceptual Ability", datPat, datUrl),
    unit("dat-reading-comprehension", "DAT · Reading Comprehension", "Reading Comprehension", datReading, datUrl),
    unit("dat-quantitative-reasoning", "DAT · Quantitative Reasoning", "Quantitative Reasoning", datQr, datUrl),
  ];

})();
